insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002041', 'agenda', '/əˈdʒendə/', 'noun', 'pauta', 'The agenda includes three main topics today.', 'A pauta inclui três tópicos principais hoje.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002042', 'key takeaway', '/kiː ˈteɪkəweɪ/', 'noun', 'principal aprendizado', 'The key takeaway is that customer feedback drives our decisions.', 'O principal aprendizado é que o feedback dos clientes orienta nossas decisões.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002043', 'audience', '/ˈɔːdiəns/', 'noun', 'plateia/público', 'The audience asked several great questions.', 'A plateia fez várias perguntas ótimas.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002044', 'overview', '/ˈoʊvərvjuː/', 'noun', 'visão geral', 'Let me give you a quick overview of the project.', 'Deixe-me dar a vocês uma visão geral rápida do projeto.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002045', 'handout', '/ˈhændaʊt/', 'noun', 'material impresso', 'You will find more details in the handout.', 'Vocês encontrarão mais detalhes no material impresso.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002046', 'structure', '/ˈstrʌktʃər/', 'noun', 'estrutura', 'A clear structure helps the audience follow your ideas.', 'Uma estrutura clara ajuda a plateia a acompanhar suas ideias.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002047', 'slide', '/slaɪd/', 'noun', 'slide', 'Please look at the chart on this slide.', 'Por favor, olhem para o gráfico neste slide.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002048', 'visual aid', '/ˈvɪʒuəl eɪd/', 'noun', 'recurso visual', 'A good visual aid makes complex data easier to understand.', 'Um bom recurso visual torna dados complexos mais fáceis de entender.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002049', 'body language', '/ˈbɑːdi ˈlæŋɡwɪdʒ/', 'noun', 'linguagem corporal', 'Confident body language makes a strong impression.', 'Uma linguagem corporal confiante causa uma forte impressão.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002050', 'eye contact', '/aɪ ˈkɑːntækt/', 'noun', 'contato visual', 'Maintaining eye contact keeps the audience engaged.', 'Manter contato visual mantém o público engajado.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002051', 'pace', '/peɪs/', 'noun', 'ritmo', 'Try to keep a steady pace when you speak.', 'Tente manter um ritmo constante ao falar.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002052', 'pause', '/pɔːz/', 'verb', 'pausar', 'It is fine to pause for a moment to collect your thoughts.', 'Tudo bem pausar por um momento para organizar seus pensamentos.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002053', 'emphasize', '/ˈemfəsaɪz/', 'verb', 'enfatizar', 'I want to emphasize the importance of this decision.', 'Quero enfatizar a importância dessa decisão.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002054', 'summarize', '/ˈsʌməraɪz/', 'verb', 'resumir', 'Let me summarize the main points before we finish.', 'Deixe-me resumir os pontos principais antes de terminarmos.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002055', 'wrap up', '/ræp ʌp/', 'verb', 'encerrar', 'We are almost out of time, so let''s wrap up.', 'Estamos quase sem tempo, então vamos encerrar.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002056', 'transition', '/trænˈzɪʃən/', 'noun', 'transição', 'A smooth transition between slides keeps the presentation flowing.', 'Uma transição suave entre os slides mantém a apresentação fluindo.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002057', 'let''s move on to', '/lets muːv ɒn tuː/', 'phrase', 'vamos passar para', 'Let''s move on to the next section.', 'Vamos passar para a próxima seção.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002058', 'as you can see', '/æz juː kæn siː/', 'phrase', 'como vocês podem ver', 'As you can see, sales grew steadily this quarter.', 'Como vocês podem ver, as vendas cresceram constantemente neste trimestre.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002059', 'handle questions', '/ˈhændəl ˈkwestʃənz/', 'phrase', 'lidar com perguntas', 'She knows how to handle questions calmly.', 'Ela sabe como lidar com perguntas com calma.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002060', 'Q&A session', '/kjuː ənd eɪ ˈseʃən/', 'noun', 'sessão de perguntas e respostas', 'We will have a Q&A session at the end.', 'Teremos uma sessão de perguntas e respostas no final.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002061', 'feel free to interrupt', '/fiːl friː tuː ˌɪntəˈrʌpt/', 'phrase', 'sintam-se à vontade para interromper', 'Feel free to interrupt if anything is unclear.', 'Sintam-se à vontade para interromper se algo não estiver claro.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002062', 'keep it concise', '/kiːp ɪt kənˈsaɪs/', 'phrase', 'manter conciso', 'Try to keep it concise so we stay on schedule.', 'Tente manter conciso para ficarmos dentro do cronograma.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002063', 'engage the audience', '/ɪnˈɡeɪdʒ ði ˈɔːdiəns/', 'phrase', 'engajar o público', 'A good story can engage the audience quickly.', 'Uma boa história pode engajar o público rapidamente.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002064', 'to sum up my presentation', '/tuː sʌm ʌp maɪ ˌprezənˈteɪʃən/', 'phrase', 'para resumir minha apresentação', 'To sum up my presentation, we exceeded our targets this year.', 'Para resumir minha apresentação, superamos nossas metas este ano.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002065', 'rehearse', '/rɪˈhɜːrs/', 'verb', 'ensaiar', 'She rehearsed her presentation several times before the meeting.', 'Ela ensaiou a apresentação várias vezes antes da reunião.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002066', 'confident', '/ˈkɑːnfɪdənt/', 'adjective', 'confiante', 'He sounded confident throughout the entire presentation.', 'Ele soou confiante durante toda a apresentação.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002067', 'filler word', '/ˈfɪlər wɜːrd/', 'noun', 'palavra de preenchimento', 'Try to avoid filler words like "um" and "uh".', 'Tente evitar palavras de preenchimento como "um" e "uh".', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002068', 'stage fright', '/steɪdʒ fraɪt/', 'noun', 'medo de palco', 'Many people experience stage fright before public speaking.', 'Muitas pessoas sentem medo de palco antes de falar em público.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002069', 'persuasive pitch', '/pərˈsweɪsɪv pɪtʃ/', 'noun', 'discurso persuasivo', 'The startup gave a persuasive pitch to the investors.', 'A startup fez um discurso persuasivo para os investidores.', 'B2', array['presentations']),
('30000000-0000-0000-0000-000000002070', 'call to action', '/kɔːl tuː ˈækʃən/', 'noun', 'chamada para ação', 'End your presentation with a clear call to action.', 'Encerre sua apresentação com uma chamada para ação clara.', 'B2', array['presentations']);

