('20000000-0000-0000-0000-000000000341', 'fill_blank', 7, '{"sentence": "You will find more details in the ___.", "options": ["handout", "agenda", "audience"], "correct": "handout", "translation": "Vocês encontrarão mais detalhes no material impresso."}'),
