('20000000-0000-0000-0000-000000000341', 'word_order', 9, '{"words": ["The", "key", "takeaway", "is", "that", "customer", "feedback", "drives", "our", "decisions"], "correct_sentence": "The key takeaway is that customer feedback drives our decisions", "translation": "O principal aprendizado é que o feedback dos clientes orienta nossas decisões"}'),
('20000000-0000-0000-0000-000000000341', 'word_order', 10, '{"words": ["The", "audience", "asked", "several", "great", "questions"], "correct_sentence": "The audience asked several great questions", "translation": "A plateia fez várias perguntas ótimas"}'),
('20000000-0000-0000-0000-000000000341', 'reading', 11, '{"passage": "Good presentations start with careful preparation. Before speaking, share the agenda so the audience knows what to expect, and think about the key takeaway you want people to remember. A short overview at the beginning and a printed handout with extra details both help the audience follow your structure.", "translation": "Boas apresentações começam com uma preparação cuidadosa. Antes de falar, compartilhe a agenda para que a plateia saiba o que esperar, e pense no principal aprendizado que você quer que as pessoas lembrem. Uma breve visão geral no início e um material impresso com detalhes extras ajudam a plateia a acompanhar sua estrutura.", "question": "What should you share before speaking, according to the text?", "options": ["The handout only", "The agenda", "The key takeaway only"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000341', 'listening', 12, '{"audio_text": "The agenda includes three main topics today. Let me give you a quick overview of the project. You will find more details in the handout.", "question": "Where can more details be found, according to the audio?", "options": ["In the agenda", "In the handout", "In the overview"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000341', 'dictation', 13, '{"audio_text": "The agenda includes three main topics today.", "expected": "The agenda includes three main topics today."}'),
('20000000-0000-0000-0000-000000000341', 'typing', 14, '{"prompt_pt": "Traduza: ''A pauta de hoje inclui uma visão geral e uma sessão de perguntas.''", "expected": "Today''s agenda includes an overview and a Q&A session.", "ai_review": true}'),

