('20000000-0000-0000-0000-000000000342', 'fill_blank', 7, '{"sentence": "Confident ___ makes a strong impression.", "options": ["body language", "eye contact", "pace"], "correct": "body language", "translation": "Uma linguagem corporal confiante causa uma forte impressão."}'),
('20000000-0000-0000-0000-000000000342', 'fill_blank', 8, '{"sentence": "Try to keep a steady ___ when you speak.", "options": ["pace", "slide", "handout"], "correct": "pace", "translation": "Tente manter um ritmo constante ao falar."}'),
('20000000-0000-0000-0000-000000000342', 'word_order', 9, '{"words": ["A", "good", "visual", "aid", "makes", "complex", "data", "easier", "to", "understand"], "correct_sentence": "A good visual aid makes complex data easier to understand", "translation": "Um bom recurso visual torna dados complexos mais fáceis de entender"}'),
('20000000-0000-0000-0000-000000000342', 'word_order', 10, '{"words": ["It", "is", "fine", "to", "pause", "for", "a", "moment", "to", "collect", "your", "thoughts"], "correct_sentence": "It is fine to pause for a moment to collect your thoughts", "translation": "Tudo bem pausar por um momento para organizar seus pensamentos"}'),
('20000000-0000-0000-0000-000000000342', 'reading', 11, '{"passage": "Nonverbal communication matters as much as words in a presentation. A clear visual aid on each slide helps explain complex ideas, while confident body language and steady eye contact build trust with the audience. Speaking at a comfortable pace, and pausing when needed, also makes a presentation easier to follow.", "translation": "A comunicação não-verbal importa tanto quanto as palavras em uma apresentação. Um recurso visual claro em cada slide ajuda a explicar ideias complexas, enquanto uma linguagem corporal confiante e um contato visual constante constroem confiança com a plateia. Falar em um ritmo confortável, e pausar quando necessário, também torna uma apresentação mais fácil de acompanhar.", "question": "What builds trust with the audience, according to the text?", "options": ["Only visual aids", "Confident body language and eye contact", "Speaking very fast"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000342', 'listening', 12, '{"audio_text": "Please look at the chart on this slide. Confident body language makes a strong impression. Maintaining eye contact keeps the audience engaged.", "question": "What makes a strong impression, according to the audio?", "options": ["The slide", "Confident body language", "Eye contact alone"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000342', 'dictation', 13, '{"audio_text": "Maintaining eye contact keeps the audience engaged.", "expected": "Maintaining eye contact keeps the audience engaged."}'),
('20000000-0000-0000-0000-000000000342', 'typing', 14, '{"prompt_pt": "Traduza: ''Um bom recurso visual, combinado com contato visual, mantém o ritmo da apresentação.''", "expected": "A good visual aid, combined with eye contact, keeps the pace of the presentation.", "ai_review": true}'),

