('20000000-0000-0000-0000-000000000343', 'multiple_choice', 4, '{"question": "I want to ___ the importance of this decision.", "audio_text": null, "options": ["emphasize", "wrap up", "pause"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000343', 'multiple_choice', 5, '{"question": "___ the next section.", "audio_text": null, "options": ["Let''s move on to", "As you can see", "To sum up"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000343', 'matching', 6, '{"pairs": [{"left": "emphasize", "right": "enfatizar"}, {"left": "summarize", "right": "resumir"}, {"left": "wrap up", "right": "encerrar"}, {"left": "transition", "right": "transição"}, {"left": "let''s move on to", "right": "vamos passar para"}, {"left": "as you can see", "right": "como vocês podem ver"}]}'),
('20000000-0000-0000-0000-000000000343', 'fill_blank', 7, '{"sentence": "Let me ___ the main points before we finish.", "options": ["summarize", "emphasize", "pause"], "correct": "summarize", "translation": "Deixe-me resumir os pontos principais antes de terminarmos."}'),
('20000000-0000-0000-0000-000000000343', 'fill_blank', 8, '{"sentence": "___, sales grew steadily this quarter.", "options": ["As you can see", "Let''s move on to", "Wrap up"], "correct": "As you can see", "translation": "Como vocês podem ver, as vendas cresceram constantemente neste trimestre."}'),
('20000000-0000-0000-0000-000000000343', 'word_order', 9, '{"words": ["We", "are", "almost", "out", "of", "time", "so", "let''s", "wrap", "up"], "correct_sentence": "We are almost out of time so let''s wrap up", "translation": "Estamos quase sem tempo, então vamos encerrar"}'),
('20000000-0000-0000-0000-000000000343', 'word_order', 10, '{"words": ["A", "smooth", "transition", "between", "slides", "keeps", "the", "presentation", "flowing"], "correct_sentence": "A smooth transition between slides keeps the presentation flowing", "translation": "Uma transição suave entre os slides mantém a apresentação fluindo"}'),
('20000000-0000-0000-0000-000000000343', 'reading', 11, '{"passage": "Skilled speakers guide the audience through a presentation with clear signals. They emphasize important points, use phrases like ''let''s move on to'' for a smooth transition, and say ''as you can see'' when pointing to data. Near the end, they summarize the main ideas and let everyone know it is time to wrap up.", "translation": "Oradores habilidosos guiam a plateia pela apresentação com sinais claros. Eles emphasize pontos importantes, usam frases como ''let''s move on to'' para uma transição suave, e dizem ''as you can see'' ao apontar para dados. Perto do fim, eles summarize as ideias principais e avisam que é hora de wrap up.", "question": "What do speakers use ''as you can see'' for, according to the text?", "options": ["To emphasize a point", "To point to data", "To wrap up"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000343', 'listening', 12, '{"audio_text": "I want to emphasize the importance of this decision. Let''s move on to the next section. As you can see, sales grew steadily this quarter.", "question": "What grew steadily this quarter, according to the audio?", "options": ["Costs", "Sales", "Complaints"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000343', 'dictation', 13, '{"audio_text": "Let''s move on to the next section.", "expected": "Let''s move on to the next section."}'),
('20000000-0000-0000-0000-000000000343', 'typing', 14, '{"prompt_pt": "Traduza: ''Como vocês podem ver, vamos passar para os próximos resultados.''", "expected": "As you can see, let''s move on to the next results.", "ai_review": true}'),

