('20000000-0000-0000-0000-000000000344', 'matching', 6, '{"pairs": [{"left": "handle questions", "right": "lidar com perguntas"}, {"left": "Q&A session", "right": "sessão de perguntas e respostas"}, {"left": "feel free to interrupt", "right": "sintam-se à vontade para interromper"}, {"left": "keep it concise", "right": "manter conciso"}, {"left": "engage the audience", "right": "engajar o público"}, {"left": "to sum up my presentation", "right": "para resumir minha apresentação"}]}'),
('20000000-0000-0000-0000-000000000344', 'fill_blank', 7, '{"sentence": "A good story can ___ quickly.", "options": ["engage the audience", "keep it concise", "handle questions"], "correct": "engage the audience", "translation": "Uma boa história pode engajar o público rapidamente."}'),
('20000000-0000-0000-0000-000000000344', 'fill_blank', 8, '{"sentence": "Try to ___ so we stay on schedule.", "options": ["keep it concise", "engage the audience", "handle questions"], "correct": "keep it concise", "translation": "Tente manter conciso para ficarmos dentro do cronograma."}'),
('20000000-0000-0000-0000-000000000344', 'word_order', 9, '{"words": ["Feel", "free", "to", "interrupt", "if", "anything", "is", "unclear"], "correct_sentence": "Feel free to interrupt if anything is unclear", "translation": "Sintam-se à vontade para interromper se algo não estiver claro"}'),
('20000000-0000-0000-0000-000000000344', 'word_order', 10, '{"words": ["To", "sum", "up", "my", "presentation", "we", "exceeded", "our", "targets", "this", "year"], "correct_sentence": "To sum up my presentation we exceeded our targets this year", "translation": "Para resumir minha apresentação, superamos nossas metas este ano"}'),
('20000000-0000-0000-0000-000000000344', 'reading', 11, '{"passage": "The way a speaker handles questions can define a presentation. Saying ''feel free to interrupt'' invites participation and helps engage the audience throughout. It is still important to keep it concise during the Q&A session, and to close with a clear phrase like ''to sum up my presentation'' before taking final questions.", "translation": "A forma como um orador handle questions pode definir uma apresentação. Dizer ''feel free to interrupt'' convida à participação e ajuda a engage the audience durante toda a apresentação. Ainda é importante keep it concise durante o Q&A session, e encerrar com uma frase clara como ''to sum up my presentation'' antes das perguntas finais.", "question": "What does saying ''feel free to interrupt'' do, according to the text?", "options": ["Ends the presentation", "Invites participation", "Keeps it concise"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000344', 'listening', 12, '{"audio_text": "She knows how to handle questions calmly. We will have a Q&A session at the end. Feel free to interrupt if anything is unclear.", "question": "When will the Q&A session happen, according to the audio?", "options": ["At the beginning", "In the middle", "At the end"], "correct_index": 2}'),
('20000000-0000-0000-0000-000000000344', 'dictation', 13, '{"audio_text": "We will have a Q&A session at the end.", "expected": "We will have a Q&A session at the end."}'),
('20000000-0000-0000-0000-000000000344', 'typing', 14, '{"prompt_pt": "Traduza: ''Para resumir minha apresentação, sintam-se à vontade para interromper durante a sessão de perguntas.''", "expected": "To sum up my presentation, feel free to interrupt during the Q&A session.", "ai_review": true}'),

