('20000000-0000-0000-0000-000000000345', 'word_order', 10, '{"words": ["The", "startup", "gave", "a", "persuasive", "pitch", "to", "the", "investors"], "correct_sentence": "The startup gave a persuasive pitch to the investors", "translation": "A startup fez um discurso persuasivo para os investidores"}'),
('20000000-0000-0000-0000-000000000345', 'reading', 11, '{"passage": "Confidence in public speaking comes from preparation. Speakers who rehearse regularly sound more confident and use fewer filler words. Even experienced presenters can feel stage fright, but practice helps. A strong persuasive pitch always ends with a memorable call to action.", "translation": "A confiança ao falar em público vem da preparação. Oradores que rehearse regularmente soam mais confident e usam menos filler words. Até apresentadores experientes podem sentir stage fright, mas a prática ajuda. Um persuasive pitch forte sempre termina com um call to action memorável.", "question": "What always ends a strong persuasive pitch, according to the text?", "options": ["A handout", "A memorable call to action", "A filler word"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000345', 'listening', 12, '{"audio_text": "She rehearsed her presentation several times before the meeting. He sounded confident throughout the entire presentation. Many people experience stage fright before public speaking.", "question": "How many times did she rehearse, according to the audio?", "options": ["Once", "Several times", "Never"], "correct_index": 1}'),
